<template><div><div v-if="!items.length" class="empty"><strong>没有符合条件的记录</strong>试试调整日期或筛选条件。</div><template v-else><div class="table-scroll desktop-records"><table class="ledger-table"><thead><tr><th v-if="selectable"><input type="checkbox" aria-label="选择本页" :checked="selected.length===items.length" @change="$emit('select',selected.length===items.length?[]:items.map(r=>r.key))"/></th><th>日期</th><th>商户 / 摘要</th><th>分类</th><th>账户</th><th>类型 / 状态</th><th class="money">金额 · {{currency}}</th></tr></thead><tbody><tr v-for="r in items" :key="r.key"><td v-if="selectable"><input type="checkbox" :aria-label="'选择 '+r.description" :checked="selected.includes(r.key)" @change="toggle(r.key)"/></td><td>{{r.date}}<div class="cell-sub">{{r.channel}}</div></td><td class="merchant"><button class="merchant-button" @click="$emit('open',r.key)">{{r.merchant||r.description||'未填写摘要'}}</button><div class="cell-sub">{{r.description!==r.merchant?r.description:r.tags.join(' · ')||'—'}}</div></td><td><span class="tag purple">{{r.categoryName||'—'}}</span></td><td>{{r.accountName||'—'}}</td><td><span class="tag" :class="r.kind==='refund'?'green':r.confirmation==='pending'?'amber':''">{{kindNames[r.kind]||r.kind}}</span><div class="cell-sub">{{r.kind==='schedule'?stateNames[r.edit.status||'estimated']:stateNames[r.confirmation]}}</div></td><td class="money"><span :class="{refund:r.kind==='refund'}">{{r.kind==='refund'?'−':''}}{{amount(r.cents,currency,show)}}</span></td></tr></tbody></table></div><div class="mobile-records"><div v-for="r in items" :key="r.key" class="mobile-record"><input v-if="selectable" type="checkbox" :aria-label="'选择 '+r.description" :checked="selected.includes(r.key)" @change="toggle(r.key)"/><button class="mobile-info" @click="$emit('open',r.key)"><strong>{{r.merchant||r.description}}</strong><div class="cell-sub">{{r.date}} · {{r.accountName||kindNames[r.kind]}}</div><span class="tag purple">{{r.categoryName||kindNames[r.kind]}}</span> <span v-if="r.kind==='schedule'" class="tag" :class="r.edit.status==='billed'?'purple':'amber'">{{stateNames[r.edit.status||'estimated']}}</span><span v-if="r.confirmation==='pending'" class="tag amber">待确认</span></button><span class="mobile-money" :class="{refund:r.kind==='refund'}">{{r.kind==='refund'?'−':''}}{{amount(r.cents,currency,show)}}</span></div></div></template></div></template>
<script setup lang="ts">
import {amount,kindNames,stateNames} from '@/api/workspace'
import type {Entry} from '@/api/workspace'
const props=withDefaults(defineProps<{items:Entry[];currency:string;show:boolean;selectable?:boolean;selected?:string[]}>(),{selected:()=>[]})
const emit=defineEmits<{(e:'open',key:string):void;(e:'select',keys:string[]):void}>()
function toggle(k:string){emit('select',props.selected.includes(k)?props.selected.filter(x=>x!==k):[...props.selected,k])}
</script>
